using namespace std;

int main() {
    char str[120], out[120];
    int out_idx = 0;
    cin >> str;
    for (int i = 0; str[i]; i++) {
        if (str[i] == 'a' && str[i + 1] == 't') {
            out[out_idx++] = '@';
            i++;
        } else if (str[i] == 'd' && str[i + 1] == 'o' && str[i + 2] == 't') {
            out[out_idx++] = '.';
            i += 2;
        } else {
            out[out_idx++] = str[i];
        }
    }
    out[out_idx] = '\0';

    if (out[0] == '@') {
        cout << "at";
    } else if (out[0] == '.') {
        cout << "dot";
    } else {
        cout << out[0];
    }

    bool first_at = true;
    for (int i = 1; i < out_idx; i++) {
        if (out[i] == '@') {
            if (first_at && i != out_idx - 1) {
                cout << '@';
                first_at = false;
            } else {
                cout << "at";
            }
        } else if (out[i] == '.') {
            if (i != out_idx - 1) {
                cout << '.';
            } else {
                cout << "dot";
            }
        } else {
            cout << out[i];
        }
    }
    cout << endl;
    return 0;
}
